import os, json
from bioblend.galaxy import GalaxyInstance
url=os.environ['GALAXY_URL']
with open(os.environ['GALAXY_API_KEY_FILE']) as fh: key=fh.read().strip()
gi=GalaxyInstance(url=url, key=key)
tool_id='toolshed.g2.bx.psu.edu/repos/iuc/samtools_view/samtools_view/1.22+galaxy2'
t=gi.tools.show_tool(tool_id, io_details=True)

def walk(inputs, prefix=''):
    for inp in inputs:
        name=inp.get('name') or ''
        p=f'{prefix}.{name}' if prefix else name
        if inp.get('model_class') in ('Conditional','Section','Repeat'):
            print(inp.get('model_class'), p, 'test=', inp.get('test_param',{}).get('name'), 'default=', inp.get('test_param',{}).get('value'))
            if inp.get('model_class') == 'Conditional':
                for case in inp.get('cases',[]):
                    print(' CASE', p, 'value=', case.get('value'))
                    walk(case.get('inputs',[]), p+'['+str(case.get('value'))+']')
            else:
                walk(inp.get('inputs',[]), p)
        else:
            if any(s in p for s in ['filter_config','output_options','subsample_config']) or name in ['input']:
                out={k:inp.get(k) for k in ['model_class','name','argument','type','label','optional','value','multiple']}
                opts=inp.get('options')
                if opts and isinstance(opts, list): out['options']=opts
                print(' FIELD', p, json.dumps(out))
walk(t['inputs'])
PY"

